/* MC Toolkit – Dangers: Danger-Profile, Mundane Dangers, Mythos-Power-Sets, Rifts (S. 140–165) */
CM_MCD["dg-mundane"] = [
 { id:"dp-intro", name:"Danger-Profile", p:141, text:[
  "Dieser Abschnitt des Buchs enthält Danger-Profile, die du in deinen Spielen nutzen kannst. Sie beschreiben Dangers aller Art und Gestalt. Er ist in drei Teile gegliedert:",
  "- **Mundane Dangers** sind gewöhnliche Individuen und Bedrohungen, die zu jeder City gehören können. Du kannst damit Sleeper-Charaktere und weltliche Bedrohungen beschreiben oder sie mit Mythos-Power-Sets kombinieren, um spontan Rifts zu erschaffen.",
  "- **Mythos-Power-Sets** sind Sets von Danger Moves, die besondere Fähigkeiten darstellen, die ein bestimmter Mythos verleiht. Du kannst sie einer Mundane Danger hinzufügen, um sofort eine einzigartige Rift zu erschaffen, etwa eine Hexen-Reporterin oder einen Hundefänger mit Jäger-Mythos.",
  "- **Rifts und andere mythische Dangers** sind vollständige Danger-Profile von Rifts und anderen mythischen Wesen (etwa von Rifts erschaffene Kreaturen) aus dem Setting von City of Mist.",
  "## Danger Rating",
  "Danger-Profile haben ein Danger Rating, das ihr Potenzial widerspiegelt, die Crew herauszufordern oder zu verletzen. Es reicht normalerweise von null (am wenigsten gefährlich) bis fünf (am gefährlichsten). Das Danger Rating steht mit einem ◆ pro Punkt neben dem Titel der Danger.",
  "Mythos-Power-Sets können das Danger Rating einer Mundane Danger erhöhen. Jedes ist mit einem + gefolgt von so vielen ◆ gekennzeichnet, wie es dem Danger Rating der kombinierten Danger hinzufügt. Eine Mundane Danger mit einem Mythos-Power-Set zu kombinieren, kann zu einem Danger Rating über fünf führen.",
  "Denk daran, dass der Schwierigkeitsgrad einer Danger stark davon abhängt, wie du als MC sie einsetzt, welche optionalen Regeln du im Spiel nutzt und wie du mit Tags und Statuses umgehst. Betrachte das Danger Rating deshalb nur als grobe Schätzung.",
  "## Kollektive Profile",
  "Danger-Profile, die ein Kollektiv beschreiben, nennen den Größenfaktor (size factor) des Kollektivs und die Danger Moves für ein einzelnes Mitglied. Wie unter „Kollektive“ (S. 126) erklärt, solltest du die Wirkung des Moves entsprechend erhöhen, wenn mehrere Mitglieder denselben Danger Move gegen dasselbe Ziel machen."]},

 { id:"dp-mundane", name:"Mundane Dangers", p:141, pe:144, text:["## Stadtbewohner"], dangers:[
  { name:"City Official", rating:1, limits:"CORRUPT 3 / LEGALLY BIND 3 / SCARE 3",
   text:["Ein City Official kann jede Person in einer formellen Position der City sein: ein Gerichtsschreiber, eine Zulassungsbeamtin, eine Politesse usw. Du kannst den City Official als gewaltfreie Barriere zwischen den Lead Characters und etwas einsetzen, das sie von der Stadtverwaltung wollen. Der City Official ist meist ein Bürokrat; er unterschreibt Papiere, gibt Informationen preis oder genehmigt Anträge der Crew nur, wenn er gesetzlich dazu verpflichtet ist.","Passe die Spektren des City Officials an, je nachdem, wie hochrangig, bestechlich oder ängstlich diese Person ist."],
   gm:["Weitere Dokumente verlangen (vexed-by-bureaucracy-2)","Sicherheitsdienst oder Polizei rufen (eine neue Danger erschaffen: Beat Cops / Security Guards)","Damit drohen, Sicherheitsdienst oder Polizei zu rufen, wenn man ihn nicht in Ruhe lässt","Das Gespräch abrupt beenden"] },
  { name:"Corporate Lawyer", rating:3, limits:"BRIBE – / DEFEAT IN COURT 5 / IMPLICATE 5 / THREATEN 4",
   text:["Dieser schleimige Rechtsberater eines Konzerns ist ein Experte darin, das Rechtssystem der City zugunsten seiner Arbeitgeber auszunutzen. Mit fettem Gehalt plus Boni lässt sich dieser Widerling nicht mit Geld beeinflussen. Und wer ihr oder den Ihren auch nur einen Finger krümmt, bekommt ernsthafte juristische Probleme – sie braucht nur einen Anlass. Du kannst dieses Danger-Profil auch für den Bezirksstaatsanwalt der City verwenden."],
   moves:[["Lawsuit","Wenn du dem Corporate Lawyer einen Status gibst, der körperlichen Schaden, Fesselung oder finanziellen Verlust beschreibt, erhältst du einen Status mit rechtlichen Folgen von derselben Stufe, etwa criminal-record-2 oder most-wanted-5."],["Objection!","Wenn der Corporate Lawyer einen rechtlichen oder Gerichts-Status erhält, senke die Stufe des Status um 2."],["Relentless","Entferne am Ende der Szene alle Statuses auf dem Spektrum threaten des Corporate Lawyers."]],
   gm:["Das Gerichtssystem gegen jemanden einsetzen (legal-trouble-3) oder in einem Prozess den Richter und/oder die Geschworenen gegen ihn einnehmen (guilty-3)","Einen Privatdetektiv losschicken, um Schmutz über jemanden auszugraben (eine neue Danger erschaffen: Detective)","Ihren Mandanten aus der Klemme holen (bis zu zwei Stufen rechtlicher Statuses entfernen)","Mit rechtlichen Schritten drohen"] },
  { name:"Helpless City Resident", rating:0, limits:"HURT OR SUBDUE 1 / SCARE 1",
   text:["Jede Person in der City, die nicht für sich selbst sorgen kann oder keine ernsthafte Bedrohung darstellt, kann als Helpless City Resident gelten. Solche Personen brauchen oft den Schutz der Crew und können die Lead Characters oder deren Gegner unterstützen.","Ein Helpless City Resident kann je nach Hintergrund einen der folgenden Moves haben:","- **Freches Kind:** einen Stein aufheben (temporary) oder eine Steinschleuder ziehen","- **Sozialarbeiterin:** jemandem helfen, damit klarzukommen (eine Stufe eines negativen emotionalen Status entfernen oder calm-1 geben)","- **Ärztin:** medizinische Hilfe leisten (eine Stufe eines negativen körperlichen Status entfernen)","- **Wissenschaftler:** jemandem sein wissenschaftliches Fachwissen anbieten","- **Rentner:** jemandem einen guten Rat geben (temporary)","- **Stylistin:** jemandem ein schnelles Make-over verpassen (fresh look)","- **Bankdirektor:** jemandem die Tresorschlüssel geben","- **Hundefänger:** jemanden oder ein Tier mit einer Hundefangstange festhalten (tangled-1)","- **Kellner:in:** sich selbst zur Notwehr schützen","- **Rockband:** diese Danger zu einem Kollektiv mit Größenfaktor 1 machen. Sie kann auch das Publikum begeistern (excite-1; als Band inflame-2)."],
   gm:["Versuchen, sich zu wehren (ouch-1)","Die Polizei rufen oder um Hilfe schreien"] },
  { name:"Mob", rating:2, limits:"QUELL 2",
   text:["Diese Danger stellt eine aufgeregte Menge von Bewohner:innen der City dar: wütende Demonstrant:innen, hysterische Fans, ein gewalttätiger Mob usw."],
   moves:[["Collective","Dieses Kollektiv hat viele Mitglieder und einen Größenfaktor von 3."],["(optional) Hard Core","Wenn quell sein Maximum erreicht, erschaffe eine neue Danger: Mob, mit einem Größenfaktor, der um eins kleiner ist als der des niedergeschlagenen Mobs. Gib dem neuen Mob einen Status violent-1."]],
   gm:["Für ihr Idol Partei ergreifen (confident-2 geben) oder die Feinde ihres Idols demütigen (humiliated-2)","Eine Barrikade, eine Polizeikette oder einen Ort überrennen (overrun-1)","Viele Leute schreien und jubeln, der Mob brodelt (sich selbst inflamed-1 geben)","Einige Leute schreien und jubeln, die Stimmung heizt sich auf"] },
  { name:"Mover & Shaker", rating:4, limits:"HURT OR SUBDUE 3 / IMPLICATE – / THREATEN 5",
   text:["Diese Danger stellt eine der mächtigsten Personen der City dar, etwa die Bürgermeisterin, einen Medienmogul oder einen Industriemagnaten. Mit einer Batterie von Anwälten und der Polizei auf der Gehaltsliste (legitim oder illegitim) lässt sich diese Person nur schwer eines Verbrechens überführen, es sei denn, die Crew gräbt echten Schmutz aus und findet einen Richter, der zuhört. Ja, viel Glück damit."],
   moves:[["Make Me an Offer I Can’t Refuse","Wenn du das Angebot eines Mover & Shaker ablehnst, gehst du Taking the Risk ein."],["Bodyguards","Wenn ein Mover & Shaker einen Status erhält, vor dem ihre Leibwächter sie schützen können, erhalten stattdessen die Leibwächter den Status (nutze SWAT Team / Elite Security für die Leibwächter)."],["Never Rest","Am Ende jeder Downtime oder als Hard Move kann der Mover & Shaker dir besmirched-reputation-3 oder wanted-3 geben oder eine neue Danger erschaffen, die dich verfolgt (wähle aus City Official, Corporate Lawyer, Detective, SWAT Team / Elite Security, Hitman usw.)."],["Relentless","Entferne am Ende der Szene alle Statuses auf dem Spektrum threaten des Mover & Shaker."]],
   gm:["Eine versteckte Waffe ziehen und angreifen (well-placed-shot-4)","Jemanden subtil und eiskalt bedrohen","Verdächtig nett zu jemandem sein"] },
  { name:"Psyche Ward Nurse", rating:1, limits:"CONVINCE 5 / HURT OR SUBDUE 2",
   text:["Wenn die Lead Characters zu viel über ihre Erfahrungen als Rifts reden, finden sie sich vielleicht einer oder mehreren dieser ausgebildeten Psychiatrie-Pflegekräfte gegenüber. Diese Pflegekraft ist es gewohnt, dass verrückte Leute behaupten, zu Unrecht festgehalten zu werden, und lässt sich daher nicht leicht beeindrucken."],
   moves:[["Hold Him Down!","Als Hard Move kann die Psyche Ward Nurse den Status-Tag eines Ziels von restrained zu sedated ändern, mit derselben Stufe."]],
   gm:["Die anderen Pfleger rufen (diese Danger wird zu einem Kollektiv mit Größenfaktor 1)","Manuell oder mit einer Zwangsjacke fixieren (restrained-3)","Die Bitten eines Patienten ignorieren (2 Stufen von überzeugenden Statuses entfernen)","Einen Patienten warnen, die Ordnung nicht zu stören, sonst …"] },
  { name:"Radical Activist", rating:2, limits:"CRIMINALIZE 3 / DELEGITIMIZE 4 / INFLAME 3 / RESTRAIN 2 / TALK SENSE 4",
   text:["Diese Person widmet sich vor allem der Förderung ihrer Sache, sei sie sozial, politisch oder ökologisch, und geht dafür unter Umständen sehr weit."],
   moves:[["Radical Action","Wenn inflame sein Maximum erreicht, Make Something Horrible Happen. Der Radical Activist stirbt, verschwindet, wird wahnsinnig, kommt ins Gefängnis usw."],["Wanted Fugitive","Wenn criminalize sein Maximum erreicht, versucht die Polizei, den Radical Activist zu verhaften. Erschaffe, wenn passend, eine neue Danger: Beat Cops."]],
   gm:["Vehement für ihre Rechte kämpfen (eine Stufe von einschränkenden Statuses entfernen)","Dich von ihrer Sache überzeugen (good-point-1)","Jemanden ausgrenzen, der ihre Sache nicht unterstützt (bad-rep-1)","Sich verbarrikadieren und sich in Schwierigkeiten bringen (sich selbst barricaded-1 und criminalized-1 geben)","Eine Szene machen und Ärger mit den Behörden bekommen"] },
  { name:"Reporter", rating:2, limits:"FOOL 3 / SCARE 4",
   text:["Fernseh-, Radio- und Zeitungsreporter sind ständig auf der Suche nach dem nächsten Scoop. Man findet sie oft dort herumschnüffeln, wo ungewöhnliche Ereignisse stattfinden, auch wenn sie die legendären Vorgänge hinter den Kulissen völlig übersehen."],
   moves:[["Inquisitive","Als Hard Move stellt dir der MC eine Frage. Du musst mit einer geraden Antwort oder einer soliden Spur antworten. Der Reporter kennt deine Antwort, auch wenn dein Charakter sie nicht ausgesprochen hat."],["On the Ball","Wenn der Reporter die Szene betritt, gib ihr alert-1."]],
   gm:["Jemanden öffentlich bloßstellen oder ihm einen schlechten Ruf anhängen (exposed-2 oder infamous-2) oder damit drohen, falls nicht …","Einen Presseausweis nutzen","Zur ungünstigsten Zeit auftauchen und herumschnüffeln","Einen unwahrscheinlichen Zeugen finden und ihn interviewen","Jemandem ein Mikrofon, eine Kamera oder einen Notizblock ins Gesicht halten und sagen, man sei live oder das Gesagte stehe in der Morgenzeitung"] },
  { name:"Social Butterfly", rating:2, limits:"BEFRIEND 5 / SHAME OR OVERSHADOW 4 / THREATEN 2",
   text:["Diese Person strotzt vor Charisma und guter Optik und kann jede gesellschaftliche Zusammenkunft beherrschen. Du kannst diese Danger für einen Promi, einen versnobten Altreichen, einen bestens vernetzten Agenten der Unterhaltungsbranche usw. nutzen."],
   moves:[["Words Can Never Hurt Me","Wenn die Social Butterfly einen unerwünschten sozialen Status erhält, senke die Stufe des Status um 1."]],
   gm:["Zum Mittelpunkt der Party werden (sich selbst center-of-attention-3 geben, temporary)","Jemanden demütigen oder beschämen (shamed-3), die Aufmerksamkeit von jemandem ablenken (ignored-3) oder jemanden unterstützen (popular-2)","Ein beiläufiges Gespräch an sich reißen und das Publikum beeindrucken"] },
  { name:"Troubled Individual", rating:1, limits:"GET INTO TROUBLE 3 / HURT OR SUBDUE 2",
   text:["Diese verzweifelte Person steuert auf eine Katastrophe zu. Von ihrer Vergangenheit und komplizierten Gefühlen heimgesucht, trifft sie immer wieder die falschen Entscheidungen und sucht oft erst dann die Hilfe der Crew, wenn es zu spät ist. Sie kann eine Showgirl sein, die in schlechte Gesellschaft geraten ist, oder ein verstörter oder suizidgefährdeter Teenager."],
   moves:[["Knack for Getting into Trouble","Am Ende jeder Downtime erhält das Troubled Individual trouble-1."],["Tragedy","Wenn get in trouble sein Maximum erreicht, Make Something Horrible Happen mit ihr."],["Mysterious Past","Wenn du einen Clue ausgibst, um eine Frage zur Vergangenheit des Troubled Individual zu stellen, kann der MC Antworten geben, die verschwommen, unvollständig oder halb wahr und halb falsch sind (wie bei der Option 7–9 von Investigate)."]],
   gm:["Jemanden dazu bringen, sie zu mögen (friendly-2)","Im ungünstigsten Moment verschwinden (Hard Move)","Die Crew warnen, dass etwas Schlimmes bevorsteht"] },
  { name:"Violent Drunk", rating:1, limits:"DETOX 4 / HURT OR SUBDUE 3",
   text:["Diese Person ist so stark berauscht, dass sie zu viel getrunken (oder zu viele Drogen genommen) hat und emotional und aggressiv geworden ist."],
   moves:[["Drown the Pain","Wenn der Violent Drunk die Szene betritt, gib ihr dulled-pain-1."]],
   gm:["Jemanden schlagen (bruise-2)","Unverständlich über ihre Vergangenheit schwafeln und jemanden dazu bringen, Mitleid zu haben (pity-1)","Randalieren und jemanden herumschubsen"] }
 ]},
 { id:"dp-krim", name:"Kriminelle", p:145, pe:147, dangers:[
  { name:"Cat Burglar", rating:2, limits:"CATCH 5 / HURT OR SUBDUE 2",
   text:["Diese erfahrene Einbrecherin knackt selbst die fortschrittlichsten Sicherheitssysteme, um an die begehrten Gegenstände zu kommen. Eine Cat Burglar kann allein oder im Team arbeiten, für sich selbst oder für einen Auftraggeber. Sie kann es auf Geld, Papiere, Schmuck oder sogar Relikte abgesehen haben."],
   moves:[["Stealthy","Wenn die Cat Burglar die Szene betritt und schleicht, gib ihr stealthy-2. Verliert die Cat Burglar diesen Status, kann der MC ihn als Hard Move erneuern."],["Fence","Zu Beginn der Downtime kann die Cat Burglar ihr kriminelles Netzwerk nutzen, um einen Gegenstand in ihrem Besitz verschwinden oder zu jemand anderem gelangen zu lassen."]],
   gm:["Sicherheitsmaßnahmen überlisten, umgehen oder entkommen (bis zu zwei Stufen von Alarmbereitschafts-Statuses bei anderen oder einen Fesselungs-Status bei sich selbst entfernen oder disabled-2 geben)","Entkommen (Deny Them Something They Want)","Mühelos durch weltliche Sicherheitssysteme schlüpfen, während die Crew zurückbleibt","Fliehen und Abstand gewinnen"] },
  { name:"Crime Lord", rating:4, limits:"HURT OR SUBDUE 3 / THREATEN –",
   text:["Der Crime Lord ist der allmächtige Herrscher eines Unterweltimperiums. Oft ein gefährlicher und gewalttätiger Mensch, ist ein Crime Lord ein furchterregender Gegner, sowohl von Angesicht zu Angesicht als auch aus der Ferne."],
   moves:[["Make Me an Offer I Can’t Refuse","Wenn du die Forderungen des Crime Lords ablehnst, gehst du Taking the Risk ein."],["Bodyguards","Wenn der Crime Lord einen Status erhält, vor dem ihre Leibwächter sie schützen können, erhalten stattdessen die Leibwächter den Status (nutze Hired Thugs für die Leibwächter)."],["Violent Tendencies","Wenn du den Crime Lord angreifst oder bedrohst, erhältst du zuerst threatened-3 oder injured-3, Wahl des MC."],["Never Rest","Am Ende jeder Downtime oder als Hard Move kann der Crime Lord dir threatened-3 geben oder eine neue Danger erschaffen, die dich verfolgt (wähle aus Corporate Lawyer oder einer beliebigen kriminellen Danger)."]],
   gm:["Jemanden brutal verprügeln, zerhacken oder erschießen (horrible-injury-4)","Schweigend beobachten und über ihr Urteil nachsinnen"] },
  { name:"Con Artist", rating:2, limits:"BUILD TRUST – / HURT 2 / THREATEN 3",
   text:["Ein Con Artist ist ein Meister der Täuschung: Sie kann dich glauben lassen, sie sei eine einfache Verkäuferin, dich um dein Erbe prellen oder dir im Gespräch eine wichtige Schlüsselkarte aus der Tasche ziehen.","Normalerweise sollte eine Täuschung innerhalb der Geschichte und ohne Regeln ausgespielt werden (weil Regeln die Existenz einer Unwahrheit verraten). Alternativ kannst du die Moves des Con Artist nutzen, um die Spieler:innen zu täuschen. Der Move Build Trust ist trügerisch: Der Con Artist gibt vor, misstrauisch zu sein, und die Spieler:innen versuchen, ihr Vertrauen zu gewinnen. Dann, in einem kritischen Moment, verrät der Con Artist die Crew und dreht den Status zu ihren Gunsten, sodass sie mit dem Geld entkommen oder einem Crewmitglied in den Rücken schießen kann. Beachte: Hat sie nicht die Fähigkeit, Mythos-Kräften zu widerstehen, kann der Con Artist keine Vertrauens-Statuses umdrehen, die mit mythischen Mitteln erzeugt wurden."],
   moves:[["(optional) Build Trust","Wenn du etwas tust, das ihr Vertrauen gewinnt, erhält sie trust-2. Versuchst du, sie zu **Convince**, kannst du wählen, ihr einen Vertrauens-Status zu geben, wenn sie dich abweist. Nutzt du ihr Vertrauen gegen sie, verlierst du ihr Vertrauen und der Status wird entfernt. Hast du genug Vertrauen aufgebaut, öffnet sie sich dir vielleicht."],["(optional) Abuse Trust","Wenn sie dich verrät, wird das Vertrauen, das du aufgebaut zu haben glaubtest, zu ihrem Vorteil. Der MC ändert den Tag trust in einen passenden positiven Status für sie, etwa underestimated oder overlooked. Nachdem sie dich verraten hat, entferne den Status."]],
   gm:["Jemanden täuschen (bis zu zwei Stufen von Alarmbereitschafts-Statuses bei anderen entfernen oder confused-2 geben)","Etwas unbemerkt stehlen (einen Tag verbrennen, der einen Gegenstand beschreibt, oder Deny Them Something They Want)","Eine versteckte Waffe ziehen und angreifen (nasty-cut-2 oder flesh-wound-2)","Sich freundlich geben und Vertrauen zu jemandem aufbauen"] },
  { name:"Delinquent Teenagers", rating:1, limits:"HURT OR SUBDUE 1 / THREATEN 1",
   text:["Rudel ungezogener Teenager sieht man oft auf den Straßen der City herumlungern, Graffiti sprühen und die Ruhe stören."],
   moves:[["Collective","Dieses Kollektiv hat mehrere Mitglieder und einen Größenfaktor von 2."]],
   gm:["Jemanden zusammenschlagen (bruise-1) oder mit Pfefferspray oder Sprühfarbe besprühen (blinded-1)","Sich gegenseitig anstacheln (fired-up-0, nur relevant, wenn der Größenfaktor angewendet wird)","Herumlungern, Lärm machen, die Ruhe stören"] },
  { name:"Getaway Vehicle", rating:2, limits:"CATCH OR OUTRUN 5 / DECOMMISSION 4",
   text:["Ein Team von Kriminellen hat meist ein Fahrzeug mit einem Fahrer in Bereitschaft in der Nähe, um so schnell wie möglich vom Tatort zu fliehen. Diese Danger kann auch einen Dragster darstellen."],
   moves:[["(optional) Vehicle","Einmal pro Szene tauchen je nach Fahrzeuggröße bis zu eine Handvoll Bewaffnete aus den Fahrzeugfenstern auf und beginnen zu schießen (nutze Hired Thugs). Die Bewaffneten steigen automatisch aus, wenn decommission sein Maximum erreicht, erhalten dabei aber hurt-1."]],
   gm:["Jemanden rammen und versuchen, ihn von der Straße zu drängen, oder scharf abbiegen, um jemanden abzuschütteln (unsteady-2)","Entkommen (Hard Move)","Beschleunigen und Abstand gewinnen"] },
  { name:"Heist Team", rating:3, limits:"DISBAND X / HURT OR SUBDUE 3 / TURN 5",
   text:["Komplexe kriminelle Operationen erfordern ein Team von Profis. Dieses Team umfasst verschiedene Spezialisten, die zusammenarbeiten, um einen Coup durchzuziehen, und jeweils eine andere Fähigkeit oder ein anderes Know-how beisteuern. Das Danger Rating ist 3+."],
   moves:[["Team","Das Spektrum disband des Heist Teams hat ein Maximum, das der Zahl der Teammitglieder minus eins entspricht. Teammitglieder erhalten Statuses auf den anderen Spektren einzeln. Wird ein Teammitglied überwältigt, umgedreht oder gefangen genommen, gib dem Team einen disband-Status mit einer um eins höheren Stufe als bisher. Wird ein Teammitglied zurückgeholt, senke die disband-Stufe um eins."],["Gambit","Einmal pro Szene ein Teammitglied zu einem anderen Typ machen."]],
   gm:["Ein Teammitglied entkommt (Deny Them Something They Want)","**Wähle die Mitglieder des Heist Teams** (jeder Typ kann mehrfach vorkommen):","**Con Artist oder Face:** jemanden täuschen (bis zu zwei Stufen von Alarmbereitschafts-Statuses bei anderen entfernen oder distracted-2 geben)","**Demolitions Expert:** Einmal pro Szene, nachdem du deinen Move angesagt hast, aber bevor du würfelst, kann der MC den Demolitions Expert als Intrusion eine Ladung zünden lassen (fatal-injury-5 oder Deny Them Something They Want).","**Ex-Military:** schießen (gunshot-wound-3) oder jemanden körperlich bezwingen (staggered-3). Wenn der Ex-Military einen Status für körperlichen Schaden oder Bezwingen erhält, senke die Stufe des Status um 1.","**Master Thief:** etwas stehlen (einen Tag verbrennen, der einen Gegenstand beschreibt, oder Deny Them Something They Want)","**Operator / Mastermind:** allen Teammitgliedern tactical-advantage-2 geben oder bis zu zwei Stufen negativer taktischer Statuses bei allen Teammitgliedern entfernen"] },
  { name:"Hired Thugs", rating:2, limits:"HURT OR SUBDUE 3 / THREATEN 4",
   text:["Diese gewöhnlichen Gauner werden angeheuert, um neugierige Reporter einzuschüchtern, aufmüpfige Nachbarn zu verprügeln, die Gegenseite mit einer Drive-by-Schießerei zu treffen oder ihren Boss und dessen illegale Geschäfte zu bewachen. Einige arbeiten für den Meistbietenden, andere sind loyal gegenüber dem, dem sie dienen, aus Angst oder wegen krimineller Zugehörigkeit."],
   moves:[["Collective","Dieses Kollektiv hat eine Handvoll Mitglieder und einen Größenfaktor von 1."]],
   gm:["Schikanieren (threatened-2), verprügeln (broken-arm-3) oder mit Kugeln eindecken (gunshot-wound-3)","Ein verwundbares Ziel ausschalten (shot-in-the-gut-4)"] },
  { name:"Petty Crook", rating:1, limits:"HURT OR SUBDUE 2 / THREATEN OR SCARE 2",
   text:["Der Petty Crook ist ein Wiesel, ein Niemand oder ein Mistkerl, der in kriminelle Aktivitäten verwickelt ist, aber in der Branche selten ernst genommen wird. Manchmal wird ein Petty Crook von einer kriminellen Organisation als billige Arbeitskraft oder für eine niedere Aufgabe angeheuert. Oft vermasselt er diesen Job und gerät in noch größere Schwierigkeiten. Am Ende will der Petty Crook niemandem wehtun, er will nur im Leben vorankommen."],
   moves:[["Bad Luck is Contagious","Einmal pro Szene kann der MC, wenn der Petty Crook anwesend ist, als Intrusion einen Hard Move machen."]],
   gm:["Mit einem Schlagring, einem Brecheisen oder einer Pistole zuschlagen (hurt-1 oder damaged-1)","Etwas Wertvolles anbieten, um seine Haut zu retten (I’m-listening-2)","Um sein Leben betteln und seine Lebensgeschichte erzählen"] },
  { name:"Hitman", rating:3, limits:"GET TO POSITION 3 / HURT OR SUBDUE 5",
   text:["Solange es menschliche Gesellschaft gibt, werden Auftragsmörder eingesetzt, um persönliche Rache zu üben oder politische Rivalen zu beseitigen. Dieses hochtrainierte Individuum ist ein professioneller Killer und Experte im Infiltrieren."],
   moves:[["Take the Shot","Wenn get-to-position sein Maximum erreicht, entferne alle Statuses auf diesem Spektrum, und der Hitman greift sein Ziel an (fatal-wound-5 oder dead-6)."],["Inscrutable","Um dem MC eine Frage über den Hitman zu stellen, musst du zwei Clues statt einem ausgeben. Nach Ermessen des MC kannst du Clues mit einem anderen Spieler kombinieren."],["(optional) Fateful Hour","Der Hitman kann „Move to position“ (siehe unten) als Soft Move nutzen."]],
   gm:["Eine Bedrohung mit Kampfkunst oder meisterhaftem Schießen ausschalten (broken-4)","In Position gehen (closing-on-target-1)","Den Schauplatz verlassen oder eine Zyankalikapsel schlucken (Hard Move)","Seine Anwesenheit (aber nicht seine genaue Position) mit einem subtilen Hinweis verraten, etwa der Spiegelung seines Zielfernrohrs oder der Bewegung seines Schattens"] },
  { name:"Smuggler", rating:2, limits:"BRIBE 4 / HURT OR SUBDUE 4 / THREATEN 5",
   text:["Schmuggler verdienen ihr Geld damit, Schmuggelware oder gestohlene Güter unbemerkt über Grenzen und an der Strafverfolgung vorbei zu bringen. Zwielichtig und gerissen, verfügen sie über ein stetig wachsendes Repertoire an Hütchenspielertricks, die sicherstellen, dass sie nie erwischt oder belastet werden."],
   moves:[["Sneaky Bastard","Wenn der Smuggler die Szene betritt, gib ihr sneaky-2. Verliert der Smuggler diesen Status, kann der MC ihn als Hard Move erneuern."],["(optional) Fleet","Der Smuggler befehligt ein Schmuggelfahrzeug (nutze Getaway Vehicle) und kann als Hard Move ein weiteres Fahrzeug rufen."]],
   gm:["Eine Kiste öffnen, eine überzogene Feuerwaffe herausziehen und sie benutzen (pumped-full-of-lead-4)","Die Umgebung nutzen, um Verfolger zu blockieren und aufzuhalten (blocked-3 oder outrun-3)","Selbst wenn sie gefasst wird, ihre Schmuggelware trotzdem am Ziel ankommen lassen (Deny Them Something They Want)","Entkommen (Deny Them Something They Want)"] }
 ]},
 { id:"dp-polizei", name:"Polizei und Sicherheit", p:148, pe:150, dangers:[
  { name:"Street Gang", rating:2, limits:"HURT OR SUBDUE 2 / RALLY 3 / THREATEN 2",
   text:["Die rauen Viertel der Stadt sind von Straßengangs überrannt. Mehr als bloße Ruhestörer und noch nicht auf einer Stufe mit dem organisierten Verbrechen, sind diese Gangs dennoch bewaffnet und gefährlich, besonders wenn ein ungebetener Besucher in ihr Revier gerät oder wenn sie eine Bedrohung ihrer Kontrolle über ihr Revier sehen."],
   moves:[["Collective","Dieses Kollektiv hat mehrere Mitglieder und einen Größenfaktor von 2."],["Home Turf","Wenn die Street Gang die Szene in ihrem Heimatrevier betritt oder wenn sie ihr Heimatrevier betritt, gib ihr home-advantage-1. Verliert die Street Gang diesen Status und befindet sich in ihrem Heimatrevier, kann der MC ihn als Soft Move erneuern, nachdem ein Spieler einen Move ohne ihn gemacht hat."],["Rally the Locals","Wenn die Street Gang in ihrem eigenen Revier ist und das Spektrum rally sein Maximum erreicht, erhöhe ihren Größenfaktor um eins (bis maximal 3)."]],
   gm:["Im Heimatrevier die lokale Bevölkerung zusammenrufen, damit sie sich ihnen anschließt (rally-2)","Jemandem Gewalt androhen (threatened-2) oder ihre Drohungen wahr machen (broken-bones-3 oder gunshot-wound-3)","Einen Eindringling oder ein Opfer in die Mangel nehmen"] },
  { name:"Beat Cops / Security Guards", rating:1, limits:"CORRUPT 2 / HURT OR SUBDUE 3 / OVERRIDE AUTHORITY 1",
   text:["Diese Danger stellt eine kleine Standardeinheit innerhalb einer größeren Polizei oder eines privaten Sicherheitsdienstes dar, meist in den untersten Rängen der Organisation, die Routineaufgaben wie Streifengänge und das Angehen von Bedrohungen vor Ort erledigt."],
   moves:[["Collective","Dieses Kollektiv hat eine Handvoll Mitglieder und einen Größenfaktor von 1."]],
   gm:["Ein Ziel körperlich bezwingen (subdued-2)","Mit halbautomatischen Pistolen oder Revolvern das Feuer eröffnen (flesh-wound-2)","Verstärkung rufen (Größenfaktor um eins erhöhen)","Sich einem Ziel nähern","Jemandem befehlen, das Gelände zu verlassen, oder „Keine Bewegung!“"] },
  { name:"Detective / Investigator", rating:2, limits:"CORRUPT 5 / HURT OR SUBDUE 3 / OVERRIDE AUTHORITY 3",
   text:["Die Polizeidetektivin oder der Privatermittler ist ein Standard des Noir-Genres. Die Detektivin kann gegen die Crew arbeiten, der Crew helfen oder eine Rivalin der Crew sein. Passe die Spektren corrupt und override-authority der Detektivin an, je nachdem, wie bestechlich bzw. wie hochrangig diese Person ist."],
   moves:[["Powers of Deduction","Wenn die Detective den Schauplatz zum ersten Mal sondiert oder als Hard Move, stellt dir der MC eine Frage. Du musst mit einer geraden Antwort oder einer soliden Spur antworten. Die Detective kennt deine Antwort, auch wenn dein Charakter sie nicht ausgesprochen hat."],["On the Ball","Wenn die Detective die Szene betritt, gib ihr alert-1."]],
   gm:["Jemanden in die Enge treiben (die Wahrheit sagen oder pressured-2 erhalten)","Einen Verdächtigen oder eine Bedrohung mit einer Feuerwaffe erschießen (gunshot-wound-3)","Einen Verdächtigen fesseln oder die Handschellen enger ziehen (handcuffed-2)","Einen Schauplatz still beobachten","Ein Beweisstück finden","Wenn allein, Verstärkung rufen"] },
  { name:"SWAT Team / Elite Security", rating:3, limits:"HURT OR SUBDUE 4",
   text:["Polizeibehörden und private Sicherheitsdienste unterhalten Einheiten hochtrainierter und bestens ausgerüsteter Beamter, die komplexe taktische Operationen durchführen können, etwa den Sturm befestigter Ziele, die Befreiung von Geiseln oder Wertgegenständen, die Sicherung einer Schlüsselposition oder sogar die Tötung eines Ziels."],
   moves:[["Collective","Dieses Kollektiv hat mehrere Mitglieder und einen Größenfaktor von 2."],["Body Armor","Wenn SWAT Team / Elite Security die Szene betritt, gib ihnen armored-1."],["Stealthy","Wenn SWAT Team / Elite Security die Szene betritt und schleicht, gib ihnen stealthy-2."]],
   gm:["Das Feuer auf ein einzelnes Ziel konzentrieren (perforated-4) oder auf mehrere Ziele verteilen (flesh-wound-2)","Ein taktisches Manöver ausführen, um die Oberhand zu gewinnen (sich selbst tactical-advantage-2 geben, bis zu zwei Stufen positiver taktischer Statuses bei nahen Zielen entfernen oder bis zu zwei Tags verbrennen, die taktische Vorteile darstellen)","Einen Ort stürmen, am liebsten indem sie sich durch ein Glasdach abseilen oder Blend- oder Rauchgranaten werfen (allen anderen temporär surprised-2, blinded-2 oder dazzled-2 geben)","Per Hubschrauber eintreffen, eine Barriere durchbrechen oder einen anderen Weg hinein finden"] },
  { name:"Police Squad Car", rating:2, limits:"DECOMMISSION 3 / OUTRUN 4",
   text:["Polizeistreifenwagen patrouillieren auf den Straßen der City und jagen Kriminelle auf Rädern."],
   moves:[["Vehicle","Wenn die Polizisten, die den Police Squad Car fahren, aussteigen, erschaffe eine neue Danger: Beat Cops. Das geschieht automatisch, wenn decommission sein Maximum erreicht, aber die Beat Cops erhalten hurt-1."]],
   gm:["Deinen Fluchtweg blockieren (blocked-3)","Während der Fahrt feuern, mit mittlerer oder tödlicher Gewalt (bean-bag-bruise-2 oder pellet-wounds-3)","Mit dem Bullenfänger rammen (smashed-4, gibt sich aber selbst damaged-1)","Ein fliehendes Ziel einholen"] },
  { name:"Security System", rating:2, limits:"ALARM 3 / OVERRIDE 4",
   text:["Vom einfachen Safe bis zum komplexen Hightech-System einer Konzernanlage dienen Einbruchsschutzmaßnahmen dazu, wertvollen Besitz zu schützen. Dieses Danger-Profil stellt ein normales Heim- oder Büro-Sicherheitssystem oder einen gewöhnlichen Safe dar; du kannst den Schwierigkeitsgrad anpassen, indem du das Spektrum alarm veränderst oder die Folgen eines Alarms abwandelst. Du könntest zum Beispiel eine Schlafgasfalle hinzufügen oder Beat Cops / Security Guards durch SWAT Team / Elite Security oder sogar einen legendären Gegner ersetzen.","Beachte, dass die Spieler:innen nicht wissen, wann das Spektrum alarm sein Maximum erreicht und der Alarm ausgelöst wird; sie sehen die Statuses, kennen aber das Maximum nicht. Sie können versuchen, per **Investigate** die interne Bedrohungsstufe des Systems einzuschätzen, wenn sie die nötigen Fähigkeiten dazu haben. Jedes Entfernen eines Status gilt dann auch für diesen Versuch."],
   moves:[["Red Alert","Wenn alarm sein Maximum erreicht, erschaffe eine neue Danger: Beat Cops / Security Guards und gib unbefugten Personen im Umkreis locked-in/out-5."]],
   gm:["Die interne Bedrohungsstufe erhöhen (sich selbst threat-1 auf dem Spektrum alarm geben)","Jeden, der versucht, es zu überbrücken, nervous-2 oder sweaty-hands-2 geben","Eine weitere Sicherheitsmaßnahme präsentieren, die überwunden werden muss, etwa ein Magnetschloss, ein Tastenfeld, einen Fensteralarm, einen Bewegungsmelder, einen unerwarteten Tresormechanismus usw."] }
 ]},
 { id:"dp-orte", name:"Orte und Gefahren", p:151, pe:152, dangers:[
  { name:"Derelict Building", rating:1, limits:"COLLAPSE 5",
   text:["Verlassene, verfallene Gebäude sind in der City ein alltäglicher Anblick. Manchmal sind sie komplett leergeräumt; manchmal enthalten sie noch die Möbel von einst, nun aber morsch und verrottend. Obdachlose, Süchtige, Kultisten und andere Ausgestoßene halten sich gern an diesen verlassenen Orten auf, ebenso viele Rifts, die eine Atempause vom Mainstream und vom Mist suchen.","Nur körperliche Statuses, die einen großen Bereich betreffen oder auf eine Schwachstelle des Derelict Building zielen, zählen gegen sein Spektrum collapse. Der MC kann außerdem entscheiden, dass passende Statuses aus **Hit With All You’ve Got** das Gebäude treffen, wenn der Angreifer nicht wählt, Kollateralschäden zu kontrollieren, oder wählt, Kollateralschäden zu verursachen."],
   moves:[["Collapse","Wenn das Spektrum collapse sein Maximum erreicht, stürzt das Gebäude ein, und alle darin erhalten buried-by-debris-5."],["Loose Debris","Immer wenn das Derelict Building einen Status auf dem Spektrum collapse erhält, fallen Trümmer von oben (bump-on-the-head-2 oder head-injury-3) auf alle darin."]],
   gm:["Eine eingestürzte Treppe, ein Loch mitten in einem Raum im ersten Stock, einen Dachboden, der nur über eine Ranke oder ein wackliges Fallrohr erreichbar ist, usw. enthüllen"] },
  { name:"House Fire", rating:2, limits:"BURNING 6",
   text:["Ob Unfall oder Brandstiftung: Ein Hausbrand kann verheerend sein und ist ab einem gewissen Punkt praktisch nicht mehr aufzuhalten. Beachte, dass Statuses auf dem Spektrum burning nur durch einen Effekt gesenkt werden können, der das gesamte Haus einschließt. Oberflächliche Kontrolle des Feuers hat keine Wirkung auf diese Danger als Ganzes."],
   moves:[["On Fire","Wenn das House Fire die Szene betritt, gib ihm burning-2 auf seinem Spektrum burning. Das House Fire kann sich als Soft Move burning-1 geben, es sei denn, sein Spektrum burning hat keine Statuses, dann ist es gelöscht."],["Go Down in Flames","Wenn das Spektrum burning sein Maximum erreicht, stürzt das Haus ein oder explodiert in einem Feuerball. Alle darin erhalten burnt-alive-6. Alle in unmittelbarer Nähe des Hauses erhalten blast-4."],["(optional) Save Me!","Wenn das House Fire die Szene betritt, sind Menschen im Haus gefangen (erschaffe eine Danger: ein oder mehrere Helpless City Resident)."]],
   gm:["Das Haus oder eine einzelne Person verbrennen (sich selbst oder jemand anderem einen burning-Status mit einer Stufe geben, die der aktuellen Stufe auf dem Spektrum burning entspricht)"] },
  { name:"Time Bomb", rating:3, limits:"DEFUSE 5 / TICKING 4",
   text:["Diese Danger beschreibt eine typische Sprengvorrichtung mit Zeitzünder. Du kannst diese Bombe anpassen, indem du die Stufe ihres tick-Status änderst, die Wirkung der Explosion änderst oder sie leichter oder schwerer entschärfbar machst."],
   moves:[["KABOOM!","Wenn das Spektrum ticking der Time Bomb sein Maximum erreicht, explodiert die Bombe. Alles und jeder im Umkreis von einer Meile erhält disintegrated-6."]],
   gm:["Jeden, der sie entschärfen will, mit bunten Kabeln verwirren (wire-dilemma-2)","Die ablaufende Zeit anzeigen (tick-1)","Jeden in der Nähe stressen (nervous-2)","Weitertickern"] },
  { name:"Junkyard Compactor", rating:2, limits:"DECOMMISSION 4",
   text:["Diese typische hydraulische Schrottplatzpresse nutzt ein Förderband und eine schwere Platte, um Metallschrott zu pressen – oder deine Crewkolleg:innen."],
   moves:[["Sturdy","Wenn der Junkyard Compactor einen Status erhält, der rohen körperlichen Schaden darstellt, senke die Stufe des Status um 2."],["Conveyor Belt","Wenn du auf das Förderband steigst, gibt dir der MC je nach deiner Position einen Status (far-1, midway-2 oder close-3). Als Soft Move kann der Junkyard Compactor die Stufe dieses Status um eins erhöhen. Dagegen kannst du kein Face Danger einsetzen. Bewegst du dich auf dem Band, senkt oder erhöht der MC die Stufe entsprechend. Steigst du vom Band, entferne den Status."],["Pancake","Wenn du auf dem Förderband-Status Stufe 5 erreichst, erhältst du pancake-6 (du kannst Face Danger einsetzen)."]],
   gm:[] },
  { name:"Citywide Epidemic", rating:3, limits:"SPREAD 6",
   text:["Wenn ein tödliches Virus aus einer streng geheimen Regierungseinrichtung ausbricht oder im Blut eines „Patient Zero“ in die Stadt gelangt, ist ein Ausbruch unvermeidlich. Diese Danger stellt eine aggressive und hochansteckende Krankheit dar, die sich potenziell über die gesamte City ausbreiten und Millionen töten könnte. Beachte, dass Statuses auf dem Spektrum spread nur durch einen Effekt gesenkt werden können, der die ganze City betrifft. Oberflächliche Kontrolle der Krankheit hat keine Wirkung auf diese Danger als Ganzes."],
   moves:[["Spreading","Wenn die Citywide Epidemic in die Geschichte eintritt, gib ihr spreading-2 auf ihrem Spektrum spread. Wenn ihr Spektrum spread keine Statuses hat, ist sie unter Quarantäne."],["Too Late","Wenn das Spektrum spread der Citywide Epidemic sein Maximum erreicht, ist es zu spät, die Ausbreitung der Krankheit zu stoppen. Die Bevölkerung der City wird dezimiert. Schneide zu einer Szene einen Monat später und beschreibe die verheerende Wirkung auf die City."],["Around the Clock","Am Ende der Downtime erhalten alle Infizierten und alle, die nicht unter Quarantäne stehen, den Status infected-1. Die Citywide Epidemic erhöht die Stufe des Status auf ihrem Spektrum spread um eins."]],
   gm:["Den Zustand einer infizierten Person verschlimmern (infected-3)"] }
 ]}
];
CM_MCD["dg-mythos"] = [
 { id:"mps", name:"Mythos-Power-Sets", p:152, pe:156, text:[
  "Mythos-Power-Sets werden einer Mundane Danger hinzugefügt, um sie zur Rift zu machen. Die Zahl hinter dem + gibt an, um wie viele ◆ sie das Danger Rating erhöhen. Die Beispiele unter jedem Namen zeigen Figuren dieses Typs."], dangers:[
  { name:"Beast +", rating:1, text:["Beispiele: Big Bad Wolf, Minotaur, Shapeshifter"],
   moves:[["Thick Hide, Wild Nature","Wenn ein Beast einen Status für körperlichen Schaden oder Bezwingen erhält, senke die Stufe des Status um 1."],["Acute Senses","Wenn ein Beast die Szene betritt, gib ihm alert-2."]], gm:["Kratzen, beißen oder zerfleischen (wounded-3)"] },
  { name:"Creature of Darkness +", rating:2, text:["Beispiele: Naga, Vampir, Wendigo"],
   moves:[["Drain Life","Als Hard Move verhängt die Creature of Darkness drained-3. Für jede Stufe von drained, die das Ziel nach Anwendung seiner Verteidigungen erhält, entfernt die Creature of Darkness eine Stufe von einem schädlichen Status, den sie hat, oder gibt sich einen positiven Status mit einer Stufe."],["(optional +◆) A Dire Enemy","Wenn du eine Creature of Darkness angreifst, erhältst du zuerst drained-3 (mit Wirkung wie oben)."]], gm:[] },
  { name:"Demigod or Giant +", rating:2, text:["Beispiele: Herkules, Gilgamesch, Paul Bunyan"],
   moves:[["Invincible","Wenn ein Demigod einen Status für körperlichen Schaden oder Bezwingen erhält, senke die Stufe des Status um 3."]], gm:["Mit gewaltiger Kraft zuschlagen oder einen Gegenstand oder eine Waffe auf jemanden schleudern (broken-4)"] },
  { name:"Golem or Elemental +", rating:1, text:["Beispiele: Golem von Prag, Vulkangott, Poseidon"],
   moves:[["Elemental Body","Wenn ein Golem oder Elemental einen Status für körperlichen Schaden erhält, senke die Stufe des Status um 2."],["Elemental Body, Part II","Wenn ein Golem oder Elemental einen Status von dem Element erhält, aus dem er besteht, wird der Status zu einem positiven Status und zählt nicht zu seinem Spektrum hurt or subdue."],["(optional +◆) Elemental Body, Part III","Wenn du einen Golem oder Elemental angreifst, erhältst du zuerst einen Status der Stufe 2, der mit dem Element zu tun hat, aus dem er besteht."]], gm:[] },
  { name:"Ghost or Spirit +", rating:1, text:["Beispiele: Ahnengeister, Nymphe, Poltergeist"],
   moves:[["Incorporeal","Ein Ghost or Spirit kann, solange er körperlos ist, keine Statuses für körperlichen Schaden oder Bezwingen erhalten. Gib seinem Spektrum hurt or subdue ein Maximum von –. Er kann keine Danger Moves nutzen, die Handlungen in der physischen Welt darstellen (sofern nicht anders angegeben)."],["(optional) Materialize","Der Ghost or Spirit kann als Hard Move körperlos werden oder sich materialisieren. Wird er körperlos, bleiben alle bisherigen Statuses erhalten und wirken weiter. Materialisiert er sich, erhält er sein ursprüngliches Maximum für hurt or subdue zurück."],["Imperceptible","Ein körperloser Ghost or Spirit kann sich als Soft Move unmerklich oder wieder wahrnehmbar machen. Solange er unmerklich ist, kannst du ihn nicht mit normalen Sinnen wahrnehmen."]], gm:[] },
  { name:"Hunter +", rating:1, text:["Beispiele: Robin Hood, Artemis, Massai-Krieger"],
   moves:[["Hunter Instincts","Wenn ein Hunter die Szene betritt, gib ihr alert-3."],["Can’t Escape","Wenn der Hunter dir einen Status für körperlichen Schaden oder Bezwingen gibt, erhältst du zusätzlich crippled-2 oder trapped-2."]], gm:[] },
  { name:"Leader +", rating:1, text:["Beispiele: Königshaus, sagenhafte Heerführerin, Volksheld"],
   moves:[["Trained Combatant","Erhöhe die Stufe der weltlichen Statuses für körperlichen Schaden oder Bezwingen, die durch die Moves des Leaders verursacht werden, um eins."]],
   gm:["Die Truppen sammeln (bis zu zwei Stufen negativer taktischer oder Moral-Statuses bei sich und anderen entfernen)","Jemandem befehlen, zu tun, was sie verlangt (compelled-3)"] },
  { name:"Messenger of the Light +", rating:1, text:["Beispiele: Engel oder Heilige, Gute Fee, ein weißer Magier"],
   moves:[["Protection from Evil","Wenn ein Messenger of the Light einen Status aus einer Quelle erhält, die von Natur aus böse oder dunkel ist, senke die Stufe des Status um 2."]],
   gm:["Jemanden segnen oder verzaubern, um ihn vor dem Bösen zu schützen (protected-2)","Die Mächte des Bösen oder der Dunkelheit verbannen (banish-3)"] },
  { name:"Mind Controller +", rating:1, text:["Beispiele: Person von unermesslicher Schönheit, Rattenfänger von Hameln, besitzergreifender Geist"],
   moves:[["Impervious","Wenn ein Mind Controller einen Status erhält, der ihrer eigenen Form der Gedankenkontrolle ähnelt, senke die Stufe des Status um 2."],["(optional +◆) Mind Reading","Als MC Intrusion kann der MC die Stufe des Einfluss-Status des Mind Controllers um eins senken, damit du eine Frage wahrheitsgemäß beantwortest. Der Mind Controller kennt nun deine Antwort."]],
   gm:["Eine Person beeinflussen, damit sie ihren Willen tut (beguiled-3, hypnotized-3, possessed-3 usw.)"] },
  { name:"Nature Spirit or God +", rating:1, text:["Beispiele: Dryade, Gaia, Kami"], moves:[],
   gm:["Wetter, Pflanzen oder Tiere nutzen, um jemandem zu schaden oder ihn einzuschränken (entangled-in-vines-3, blown-away-3, stuck-in-quicksand-3, viciously-bitten-3)","Das Wetter verändern und einen Story Tag wie lashing rain, fog, sunshine usw. erschaffen","Lebewesen heilen (bis zu eine Stufe von Statuses für körperlichen Schaden entfernen)"] },
  { name:"Necromancer +", rating:2, text:["Beispiele: Baron Samedi, Hades, Hexe von Endor"],
   moves:[["Bodyguards","Wenn die Necromancer einen Status erhält, vor dem ihre Leibwächter sie schützen können, erhalten stattdessen die Leibwächter den Status."],["Speak to the Dead","Als Hard Move stellt dir der MC eine Frage. Du musst mit einer geraden Antwort oder einer soliden Spur antworten. Die Necromancer kennt deine Antwort, auch wenn dein Charakter sie nicht ausgesprochen hat."]],
   gm:["Die Toten erwecken (eine neue Danger erschaffen: Undead, mit einem Spektrum hurt:3, einem Größenfaktor von 1 und der Fähigkeit, slashed-3 zuzufügen)"] },
  { name:"Sorcerer or Witch +", rating:1, text:["Beispiele: Balor vom bösen Blick, Böse Hexe des Westens, Morgana"],
   moves:[["Sorcery","Einmal pro Szene kann ein Sorcerer or Witch als Intrusion drei Story Tags erschaffen. Außerdem kann ein Sorcerer or Witch als Hard Move einen Story Tag erschaffen. Der Story Tag kann Schutzmittel, Umwelteffekte, beschworene Verbündete oder Fähigkeiten und Eigenschaften beschreiben, die sich der Sorcerer or Witch selbst geben kann."],["(optional +◆) Dark Magick","Um einen Story Tag zu verbrennen, den ein Sorcerer or Witch erschaffen hat, musst du zwei Punkte Juice statt einem ausgeben."],["(optional –◆) Hedge Magick","Die Story Tags, die ein Sorcerer or Witch erschafft, sind temporary."]],
   gm:["Mit Magie angreifen (einen passenden Status geben, dessen Stufe der Zahl der Story Tags entspricht, die am Angriff teilnehmen oder ihn verstärken)"] },
  { name:"Swift-Footed +", rating:1, text:["Beispiele: Der Hase (und der Igel), Merkur, Affenkönig"],
   moves:[["Runner","Der Swift-Footed hat ein Spektrum outrun:5."]],
   gm:["Mit voller Geschwindigkeit in jemanden hineinrennen (mild-concussion-3)","Jemandem etwas aus der Hand oder Reichweite schnappen (einen Tag verbrennen, der einen Gegenstand beschreibt, oder Deny Them Something They Want)"] },
  { name:"Thief +", rating:1, text:["Beispiele: Goldlöckchen, Hans und die Bohnenranke, Prometheus"],
   moves:[["Stealthy","Wenn ein Thief die Szene betritt und schleicht, gib ihr stealthy-4. Verliert der Thief diesen Status, kann der MC ihn als Hard Move erneuern."]],
   gm:["Etwas unbemerkt stehlen (einen Tag verbrennen, der einen Gegenstand beschreibt, oder Deny Them Something They Want)"] },
  { name:"Trickster +", rating:1, text:["Beispiele: Feen und Kobolde, Gestiefelter Kater, Trickstergott"],
   moves:[["Deceitful","Wenn du einen Clue ausgibst, um eine Frage über den Trickster zu stellen, kann der MC Antworten geben, die verschwommen, unvollständig oder halb wahr und halb falsch sind (wie bei der Option 7–9 von Investigate)."]],
   gm:["Jemanden überzeugen, einen bestimmten Weg einzuschlagen (convinced-3)","Ein trügerisches oder falsches Äußeres annehmen (sich selbst einen Story Tag geben)"] },
  { name:"Warrior +", rating:1, text:["Beispiele: Ritter der Tafelrunde, David & Goliath, Samurai"],
   moves:[["Trained Combatant","Erhöhe die Stufe der weltlichen Statuses für körperlichen Schaden oder Bezwingen, die durch die Moves des Warriors verursacht werden, um eins."],["Unbeatable","Wenn ein Warrior die Szene betritt, gib ihr drei defensive Story Tags wie Rüstung, Schild, Helm, Parade, Ausweichen, Block, Rutschen, Sprung usw."],["Legendary Swordsmanship","Wenn du einen Warrior angreifst, erhältst du zuerst einen Status der Stufe 2, der mit ihrer Kampfkunst zu tun hat. (Trained Combatant gilt hierfür nicht.)"]], gm:[] },
  { name:"Weapon Bearer (Relic) +", rating:2, text:["Beispiele: Blitz des Zeus, Das Flammenschwert, Speer des Schicksals"],
   moves:[["It Blocks By Itself","Wenn ein Weapon Bearer die Szene betritt, gib ihr defensive-maneuvers-3. Das gilt für jeden Angriff, den ihr Relikt abwehren kann. Verliert sie diesen Status, kann der MC ihn als Soft Move erneuern, nachdem ein Spieler einen Move ohne ihn gemacht hat."]],
   gm:["Jemanden mit ihrer Waffe niederstrecken (ein passender Status der Stufe 4)","Eine weitere Person oder einen weiteren Gegenstand mit ihrer Waffe schützen (defensive-maneuvers-3)"] },
  { name:"Winged Creature +", rating:1, text:["Beispiele: Fliegende Affen, Pegasus, Quetzalcoatl"],
   moves:[["Take Flight","Eine Winged Creature hat entweder dauerhaft einen Story Tag wings oder kann sich jederzeit Flügel geben und den Tag nach Belieben ablegen."]],
   gm:["Herabstoßen und mit Klauen oder Schnabel zuschlagen (slashed-3)","Davonfliegen und der Gefangennahme entgehen (Deny Them Something They Want)"] }
 ]}
];
CM_MCD["dg-rifts"] = [
 { id:"rifts", name:"Rifts und andere mythische Dangers", p:157, pe:164, text:["Die folgenden Profile gehören zu Figuren der Stadtbezirke aus Kapitel 1. Die Beschreibungen mit Verweis auf eine Seite findest du dort."], dangers:[
  { name:"Alice (Alice im Wunderland)", rating:5, limits:"ALTER – / HURT OR SUBDUE –",
   text:["Downtown. Die Beschreibung dieser Figur steht auf S. 24.","Alice ist die stärkste Realitätsverbiegerin der City. Zum Pech aller anderen ist sie außerdem ein totaler Wirrkopf und hat absolut keine Kontrolle über ihre Kräfte – und strebt sie auch nicht an. Niemand weiß wirklich, was mit dieser verrückten Herumtreiberin los ist oder woher sie kam, auch wenn einige der besser informierten Wesen der City vermuten, dass sie aus dem Wunschbrunnen eines nahen Dorfes hervorging. Es ist unklar, ob sie ein Avatar, eine extrem mächtige Rift oder etwas anderes ist. Avatare halten sich von ihr fern, aus Furcht vor seltsamen und unerwarteten mystischen Folgen. Nur wenige wissen es, aber selbst die Gatekeeper sind verstört von dem, was sie kann, und von ihrer Widerstandskraft gegen deren Methoden."],
   moves:[["Pandemonium","Wenn Alice einen veränderten Bewusstseinszustand erlebt, erhält alles in ihrem Blickfeld bedlam-5, unter Umgehung von Face Danger oder anderen Verteidigungen. Logik, Proportion und die Gesetze der Physik lösen sich auf. Dinge und Menschen werden zu völlig anderen Dingen und Menschen. Kehrt Alice zu einem normalen Bewusstseinszustand zurück, kehrt alles zur Normalität zurück. Der Status bedlam-5 wird zu dormant-bedlam-5. Das Pandemonium wird ausgelöst, wenn jemand versucht, Alice anzugreifen oder in irgendeiner Weise zu verändern."],["Subsequent Pandemonium","Wenn du auf einem Pandemonium-Status Stufe 6 erreichst, wähle zufällig ein Theme (würfle oder zieh eines, ohne die Karten zu sehen). Du ersetzt dieses Theme. Der Status der Stufe 6 wird zu dormant-bedlam-5."],["Utter State of Chaos","Wenn du Stop. Holding. Back. nutzt, um gegen Alices Kräfte zu kämpfen, musst du ein Significant-Opfer bringen, um einen kleinen Bereich im Pandemonium zu stabilisieren, ein No-Return-Opfer, um den Pandemonium-Status von jemandem zu entfernen, und das Ultimate-Opfer, um das Pandemonium zu beenden, ohne dass jemand Statuses erhält."],["Redefined Essence","Wenn du Realitätsverbiegung nutzt, um die Pandemonium-Statuses zu verändern, gilt das Entfernen des Status, den du zu entfernen versuchst, auch für deinen Versuch."]],
   gm:[] },
  { name:"The Reeds (Nature Boy)", rating:3, limits:"HARM ZEBEDEE 1 / HARM THE BOY 1",
   text:["Downtown. Die Beschreibung dieses Ortes steht auf S. 22.","„The Reeds“ ist die Heimat der weisesten Person der City, eines namenlosen Jungen, der in einer Enklave lebt, die wie ein Flussufer aussieht. In zerrissenen Leinenshorts sonnt sich dieser Junge, tut so, als angle er, und schwimmt ab und zu kurz. Manchmal unternimmt er einen Ausflug durch die City, kehrt aber immer in seine Enklave zurück. Der Torhüter der Enklave ist Zebedee Jackson, ein blinder Saxofonist. Ihm wurde die Weisheit geschenkt, anderen zu helfen, und wenn er es nicht kann, zu sehen, ob sie des Rates des Jungen würdig sind."],
   moves:[["Zebedee","Wenn Zebedee dir eine Frage stellt, musst du wahrheitsgemäß antworten oder afraid-to-know-5 erhalten. Hast du Angst zu wissen, bringt Zebedee dich nicht zum Jungen."],["Just To Love","Wenn du in „the Reeds“ eine Handlung vornimmst, die von Bosheit oder Eigennutz getrieben ist, hörst du eine alte Jazzmelodie im Kopf. Du musst zuerst Face Danger gegen overwhelmed-by-emotion-5 einsetzen."],["The Greatest Thing You’ll Ever Learn","Für jeden Power Tag, den du hast und der wahre Liebe darstellt, beantwortet Nature Boy eine Frage. Du erhältst einen Clue, aber der MC muss ihn mit einer geraden Antwort beantworten. Denselben Tag kannst du mit diesem Move nie wieder nutzen. Wenn du nicht wahre Liebe zeigst, kann der Junge deine Fragen nicht beantworten, selbst wenn du ihn zwingst."]],
   gm:[] },
  { name:"Rachel Delaney (Rapunzel)", rating:2, limits:"HURT OR SUBDUE 2",
   text:["Downtown.","In einem gesicherten Penthouse in Downtown wird Rachel Delaney von einer mächtigen Person gegen ihren Willen festgehalten. Alle ihre Bedürfnisse werden erfüllt, aber sie kann nicht gehen. Ihre Entführer halten sie schlicht für zu wertvoll, und vielleicht haben sie recht. Rachels Haar ist etwas ganz Besonderes: Es befördert Menschen auf magische Weise von einem Ort zum anderen. Rachel selbst hat darum nicht gebeten. Sie hat versucht zu fliehen, vergeblich. Sie ist schon früher entkommen, aber ihre Entführer fanden sie und brachten sie zurück. Mit jedem Tag wird sie bitterer."],
   moves:[["Transported","Wenn du an einem von Rachels Haaren ziehst, wirst du dorthin befördert, wo sich der Rest dieses Haares befindet (ob es nun an Rachels Kopf hängt oder nicht). Das gesamte Haar zerfällt dann zu Staub."]],
   gm:["Jemandem eines ihrer unversehrten Haare geben (Rachels Haar, temporary)","Jemanden anflehen oder manipulieren, ihr bei der Flucht zu helfen (pity-3)","Jemanden mit einer versteckten Handfeuerwaffe erschießen (shot-in-the-gut-4)","Den Sicherheitsdienst rufen (eine Danger erschaffen: SWAT Team / Elite Security)"] },
  { name:"Jacqueline Brown (Hans und die Bohnenranke)", rating:3, limits:"CATCH 5 / HURT OR SUBDUE 2",
   text:["Arbeiterviertel. Die Beschreibung dieser Figur steht auf S. 30."],
   moves:[["Stealthy","Wenn Jacqueline Brown die Szene betritt und schleicht, gib ihr stealthy-2. Verliert sie diesen Status, kann der MC ihn als Hard Move erneuern."],["Green-thumbed","Als Soft Move kann Jacqueline Brown dort, wo sie steht, aus der Erde eine riesige Bohnenranke wachsen lassen oder eine mit einer Berührung zerstören. Einmal pro Szene kann sie das als MC Intrusion tun. Alle und alles, was von der Bohnenranke getragen wird, beginnt zu fallen, wenn sie sie zerstört, und muss Take the Risk und/oder Face Danger einsetzen."],["Giant Slayer","Erhöhe die Stufe jedes Status für körperlichen Schaden, den Jacqueline Brown übergroßen menschenähnlichen Kreaturen zufügt, um eins."]],
   gm:["Jemanden mit einer Pistole erschießen, die sie bei sich trägt (gunshot-wound-3)"] },
  { name:"Samuel Valtierra (Baron Samedi)", rating:5, limits:"",
   text:["Arbeiterviertel. Die Beschreibung dieser Figur steht auf S. 30.","Samuel Valtierras Fähigkeiten lassen sich durch die Danger Crime Lord in Kombination mit dem Mythos-Power-Set Necromancer darstellen. Statt Undead ruft Valtierra jedoch seine Zombies herbei, lebende Gangmitglieder, die ihn verraten haben und die er als seine Diener von den Toten zurückgeholt hat. Sie sind eine Danger mit einem Spektrum hurt:5, einem Größenfaktor von 1 und der Fähigkeit, ferocious-bite-3 zuzufügen. Außerdem kann Valtierra den Tod einer Person verhindern und sogar umkehren, wie im folgenden Move beschrieben; diese Fähigkeit hat ihn in direkten Konflikt mit dem Avatar des Hades, Anatoli Vidales, gebracht (siehe S. 174)."],
   moves:[["Nobody dies unless I say so","Valtierra kann eine Person wieder zum Leben erwecken. Dazu muss er einen Körper berühren, der bis zu drei Tage zuvor gestorben ist. Die wiederbelebte Person steht völlig geheilt auf, auch wenn Krankheiten und chronische Leiden bestehen bleiben können. Der MC bestimmt, welche Statuses die wiederbelebte Person behält. Valtierra kann auch wählen, eine Person als willenlosen Zombie unter seiner Kontrolle wiederzubeleben und ihr zombie-5 zu geben."]],
   gm:[] },
  { name:"Magic Sword (Flammenschwert von Eden)", rating:4, limits:"EXHAUST 5 / HURT OR SUBDUE – / MYSTICALLY BIND 5",
   text:["Altstadt.","Dieses magische Schwert wurde von der Museum Watch (der Ad-hoc-Gruppe von Selbstjustizlern, die das Museum schützen, erwähnt auf S. 34) aufgestellt, um die Schätze des Museums vor Dieben, Einbrechern und Plünderern zu schützen. Es kann nicht zerstört werden, aber ihm kann die magische Energie ausgehen, wenn es sich im Kampf gegen einen mächtigen Eindringling verausgabt. Das Schwert ist ein Wächter, kein Killer; wenn es nicht unbedingt nötig ist, wendet es keine tödliche Gewalt an. Stattdessen versucht es, Eindringlinge bewusstlos zu machen, damit die Museum Watch sie hinaustragen kann."],
   moves:[["Resistant to Magic","Solange das Flammenschwert nicht völlig erschöpft ist, kann es keine Statuses auf seinem Spektrum mystically-bind erhalten."],["Mystical Object","Wenn das Spektrum mystically-bind sein Maximum erreicht, gehorcht das Schwert den Befehlen dessen, der es gebunden hat."],["Mystical Sense","Das Schwert kann Wesen und mystische Energien in seiner Umgebung spüren. Wenn es die Szene betritt, gib ihm mystically-aware-4. Verliert es diesen Status, kann der MC ihn als Soft Move erneuern, nachdem ein Spieler einen Move ohne ihn gemacht hat, aber das Schwert erhält exhausted-1. Dieser Status kann Stufe 4 nicht überschreiten."]],
   gm:["Mit seiner flammenden Klinge zuschlagen (burning-injury-3)","Einen Eindringling aufspießen (burning-sword-through-the-heart-6, aber das Schwert erhält exhausted-3)","Die Umgebung mit mystischem Feuer überziehen und dabei nur sein Ziel bzw. seine Ziele verletzen (holy-burns-5, aber das Schwert erhält exhausted-2)","Die Museum Watch magisch alarmieren (eine Danger erschaffen: Heist Team)","In den Gängen des Museums schweben und nach Eindringlingen suchen","Mit maximaler Geschwindigkeit auf ein Ziel zufliegen"] },
  { name:"Paul Dumont / „The Gargoyle“ (Quasimodo)", rating:3, limits:"HURT OR SUBDUE 4",
   text:["Altstadt. Die Beschreibung dieser Figur steht auf S. 37.","Als Paul Dumont das Tagebuch der früheren „verfluchten“ Mitglieder der Familie Dumont fand, erkannte er, was seine Vorfahren vor ihm entdeckt hatten: Die „Verfluchten“ wurden erschaffen, um Korruption zu bekämpfen, besonders die der „gesegneten“ Familienmitglieder. Der Fluch hatte einen Weg gefunden, sich auszugleichen – und er war dieser Weg. Nachts streift Paul über die Dächer als der berühmte Selbstjustizler „der Gargoyle“, ein Name, den er von den früheren „verfluchten“ Mitgliedern seiner Familie geerbt hat."],
   moves:[["Scandalous","Wenn der Gargoyle auf der Straße den Boden berührt, folgt sofort ein Skandal: Entweder sieht ihn jemand, und bald sammelt sich ein Mob, um ihn zu fassen (eine Danger erschaffen: Mob), oder der MC kann Make Something Horrible Happen."],["Stoneskin","Wenn der Gargoyle einen Status für körperlichen Schaden erhält, senke die Stufe des Status um 3."],["Gear","Wenn der Gargoyle die Szene betritt, gib ihm einen Kapuzenpulli, eine Enterhakenpistole und einen Gleiter. Wird einer dieser Tags entfernt, kann der MC einen als Hard Move erneuern, wenn der Gargoyle ihn plausibel zurückholen kann."]],
   gm:["Ein Gebäude hinaufklettern, Deckung suchen und sich auf den Sturzflug vorbereiten (sich selbst superior-position-3 geben)","Mit Steinklauen zerfetzen (gash-3), mit Kampfkunst überwältigen (staggered-3) oder jemandem eine Bola zuwerfen (entangled-3)","In den Schatten schleichen"] },
  { name:"Spider (Spinnenfrau)", rating:3, limits:"HURT OR SUBDUE 5",
   text:["Industriezone. Die Beschreibung dieser Figur steht auf S. 43."],
   moves:[["Spider Senses","Wenn Spider die Szene betritt, gib ihm alert-3."],["Tough Son of a Gun","Wenn Spider einen Status für körperlichen Schaden oder Bezwingen erhält, senke die Stufe des Status um 1."],["Dreamcatcher","Für jede Stufe von restrained, die Spider einem Ziel gibt, kann er einen seiner Mythos-Power-Tags verbrennen (bei einem PC) oder eine seiner legendären Move-Wirkungen um eins senken (bei einer Danger)."],["Decommission","Als Soft Move kann Spider einem Ziel mit restrained-5 einen zusätzlichen Status no-Mythos-powers-5 geben, gegen den das Ziel kein Face Danger einsetzen kann."],["Net Trap Landmine","Einmal pro Szene erhältst du, wenn du versuchst, Spider anzugreifen, zuerst restrained-5."]],
   gm:["Ein Ziel mit einem Kabelbinder (ziplock-2) fesseln oder mit seiner Schrotflinte ein Netz abfeuern (tied-up-4)","Lautlos auftreten und die Umgebung sondieren","Jemanden warnen, freiwillig mitzukommen, sonst …"] },
  { name:"Lily Chow (Eisenhans)", rating:4, limits:"BANISH HANS 5 / HURT OR SUBDUE HANS – / HURT OR SUBDUE LILY 2",
   text:["Industriezone. Die Beschreibung dieser Figur steht auf S. 42.","Lily Chow kann eines der mächtigsten Wesen der City herbeirufen (oder beschwören), das ihr zu Hilfe kommt, aber sie kann es nicht lange aufrechterhalten. Eisenhans ist ein grüner Riese aus purer magischer Energie, größtenteils unverwundbar und zu praktisch jeder magischen Leistung fähig. Obwohl er mächtig und weise erscheint, ist Eisenhans ganz Lily und ihrer Erkundung der City verpflichtet. Wenn sie ihn etwas fragt, rät er ihr, aber meist wacht er nur über sie. Entwickelt sich Lily im Laufe der Serie weiter, kannst du ihre Spektren erhöhen oder ihren Kampfkunst-Move verbessern oder den Status flicker von einigen von Hans’ Moves entfernen."],
   moves:[["Cheeky Brat","Wenn Lily Chow die Szene betritt, gib ihr indignant-3. Verliert sie diesen Status, kann der MC ihn als Hard Move erneuern."],["Gutter Out","Wenn das Spektrum banish Hans sein Maximum erreicht, verschwindet Eisenhans. Lily Chow kann ihn in dieser Szene nicht erneut herbeirufen."],["Energy Hulk","Jedes Mal, wenn Eisenhans einen Status für körperlichen Schaden erhält, ignoriert er ihn, und Lily erhält flicker-1 auf dem Spektrum banish Hans. Als Soft Move (oder MC Intrusion, wenn Lily in Gefahr ist) kann Eisenhans sich bewegen und bis zu eine Handvoll Menschen in sich aufnehmen. Wer sich in Eisenhans befindet, kann keine Statuses für körperlichen Schaden oder Bezwingen erhalten."],["Magician","Einmal pro Szene kann Eisenhans als Intrusion drei Story Tags erschaffen. Als Hard Move kann er einen Story Tag erschaffen. Nach beiden Aktionen erhält Lily flicker-1 auf dem Spektrum banish Hans. Die Story Tags können Schutzmittel, Umwelteffekte, beschworene Verbündete oder Fähigkeiten und Eigenschaften beschreiben, die Eisenhans sich selbst oder Lily geben kann."],["Stop. Holding. Back.","Lily kann Hans wachsen lassen, damit er mehrere Personen vor einem Status für körperlichen Schaden schützt (Größenfaktor 2), oder seine gesamte Energie auf einen tödlichen Schlag konzentrieren, indem sie zwei Schutz-Tags verbrennt (oder die Verteidigung eines Ziels anderweitig um 2 senkt) und dann cut-in-half-6 verhängt. Eisenhans verschwindet, und Lily Chow kann ihn bis zum Ende der nächsten Downtime nicht erneut herbeirufen."]],
   gm:["Eisenhans zum Angriff befehlen, mit einem der folgenden: mit einer magischen Energieaxt spalten (gaping-gash-5) oder mit einem Faustschlag, einem Tritt oder dem Axtstiel treffen (barely-standing-4). Lily erhält flicker-1 auf dem Spektrum banish Hans.","Mit einfacher Kampfkunst sich selbst schützen (sich selbst defensive-stance-1 geben und jemandem prone-2, temporary, oder dizzy-2 geben)","Jemandem drohen, sich nicht mit ihr anzulegen","Sich wie eine Göre benehmen und empört widersprechen"] },
  { name:"Chinthe Statues (Chinthe)", rating:3, limits:"DAMAGE 4 / REVERT 4",
   text:["Anderswo. Die Beschreibung dieser Figur steht auf S. 45.","Die Chinthe-Statuen sind Relikte, die seit drei Generationen Erbstücke der Familie Wong sind. Beim kleinsten Zeichen eines Eindringlings oder einer Bedrohung für den Laden der Wongs erwachen diese Statuen als Wächterlöwen zum Leben und fesseln oder töten den Eindringling, je nach Befehl ihres Herrn. Da die lebenden Chinthe Kreaturen sind, die von jenseits des Mist beschworen wurden, können einige Zauberer sie mit den richtigen Zaubern wieder in Steingestalt zurückverwandeln; als himmlische Wächter sind diese Statuen jedoch gegen dunkle Magie immun. Dieses Danger-Profil stellt eine einzelne Statue dar."],
   moves:[["Guardian Lions","Wenn du in der Nähe der Chinthe **Investigate** oder **Sneak Around** einsetzt und 7–9 erzielst, kann der MC wählen, die Chinthe zu erwecken, statt aus der Move-Liste zu wählen. Sind die Chinthe wach, weiß ihr Herr davon und kann durch ihre Augen und Ohren sehen und hören, bis sie zur Statuengestalt zurückkehren."],["Celestial Beings","Wenn ein Chinthe einen Status für körperlichen Schaden oder Bezwingen erhält, senke die Stufe des Status um 2. Erhält ein Chinthe einen Status durch dunkle Magie, ignoriere den Status."]],
   gm:["Ein einzelnes Ziel anspringen und niederhalten (held-down-3)","Jemanden mit goldenen Klauen beißen oder zerkratzen (slash-3)","Jenseitige Kreaturen verbannen und/oder dunkle Magie bannen (banish-5 oder fünf Tags verbrennen, die solche Kreaturen beschreiben)","Beim ersten Anzeichen eines Eindringlings erwachen"] },
  { name:"Gatekeeper Agents", rating:3, limits:"HURT OR SUBDUE 4",
   text:["Von den vielen verschiedenen Einheiten, die den Gatekeepern zur Verfügung stehen, sieht man am häufigsten die Feldagenten im aktiven Dienst. Neben ihrer umfassenden weltlichen Ausbildung sind Gatekeeper-Agenten in der Kunst des Shrouding geschult, der Manipulation des Mist. Gatekeeper nehmen manchmal eine weltliche Tarnung an, die vom Mist erschaffen wird. Du solltest diese falsche Identität als völlig normale und unverdächtige Figuren erzählen. Willst du den Spieler:innen die Chance geben, die Gatekeeper zu entlarven, kannst du schwache Hinweise auf die falschen Identitäten streuen. Nutze den Move Creepy Feeling, wenn die Lead Characters bereits etwas vermuten und beschließen, zu **Investigate**; er spiegelt die Schwierigkeit wider, konkrete Informationen über die Tarnung der Gatekeeper zu erhalten. Wenn du den Spieler:innen Creepy Feeling offenbarst, verwende den Namen der falschen Identitäten der Gatekeeper (statt „Gatekeeper Agents“), um die Gatekeeper nicht automatisch zu enttarnen."],
   moves:[["Collective","Dieses Kollektiv hat eine Handvoll Mitglieder und einen Größenfaktor von 1."],["Creepy Feeling","Wann immer du versuchst, per **Investigate** mehr über [Name der falschen Identität] herauszufinden, bekommst du ein seltsames Gefühl, dass er / sie undurchdringlich ist. [Er / Sie] erhält mysterious-2. Dieser Status kann Stufe 4 nicht überschreiten."],["Explosive Shrouding Ward","Einmal pro Szene erhalten als Intrusion alle um die Gatekeeper herum oblivious-5. Nach Wahl der Gatekeeper können sie die Szene fliehend verlassen."],["Defensive Shrouding","Einmal pro Szene, wenn du Gatekeeper Agents mit Mythos-Kräften angreifst, manipulieren sie den Mist, um deine Kräfte zu ersticken. Der MC verbrennt zuerst zwei Power Tags, die mit deinem Angriff zu tun haben."]],
   gm:["Jemanden verschleiern, sodass er sich nicht erinnert (vague-memories-3)","Jemandes Mythos verschleiern, sodass er seine Kräfte verliert (zwei Mythos-Power-Tags verbrennen oder die Move-Wirkung einer Danger um zwei senken)","Eine Standard-Pistole abfeuern (gunshot-wound-3) oder einfache Kampfkunst einsetzen (hold-down-2 oder bruise-2)","Aus dem Nichts auftauchen","Allen sagen, dass sie sich bald an nichts hiervon erinnern werden"] }
 ]}
];
